contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(string calldata description) public {
        address caller = address(this);
        bool wasAdmin = c.isAdmin(caller); if (__ESBMC_reverted()) return;

        bool reverted;
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted ? !wasAdmin : wasAdmin && c.isAdmin(caller) == wasAdmin);
    }

    receive() external payable {}
}

