pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(string memory description) internal {
        address caller = address(this);
        bool wasAdmin;
        try c.isAdmin(caller) returns (bool __r) { wasAdmin = __r; } catch { return; }
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted ? !wasAdmin : wasAdmin && c.isAdmin(caller) == wasAdmin);
    }

    function testFuzz_run(string memory description) public {
        _run(description);
    }

    receive() external payable {}
}
